def get_aisle_positions(aisle_counts: list, num_aisles: int) -> list:
    positions = []
    while num_aisles > 0:
        max_count = max(aisle_counts)
        positions.append(aisle_counts.index(max_count))
        aisle_counts[aisle_counts.index(max_count)] = 0
        num_aisles -= 1
    return positions

def max_energy(beads):
    # Initialize a dictionary to store the maximum energy for each possible start position
    max_energies = {}
    for i in range(len(beads)):
        # Initialize the maximum energy for the start position i to be the energy of the first bead
        max_energies[i] = beads[i]
        for j in range(i+1, len(beads)):
            # Compute the energy for merging the beads at positions i and j
            energy = beads[i] * beads[j] * beads[(j+1) % len(beads)]
            # Update the maximum energy for the start position i if necessary
            max_energies[i] = max(max_energies[i], energy)
    # Return the maximum energy for any start position
    return max(max_energies.values())

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    Args:
        n (int): The highest degree of the polynomial.
        coeffs (List[int]): A list of coefficients, starting with the coefficient of the highest degree term.

    Returns:
        str: The string representation of the polynomial.
    """
    terms = []
    for i, coeff in enumerate(coeffs):
        if coeff != 0:
            degree = n - i
            if degree == 0:
                terms.append(str(coeff))
            elif degree == 1:
                terms.append(f"{coeff}x")
            else:
                terms.append(f"{coeff}x^{degree}")
    return " ".join(terms)

def count_coprime_pairs(x0: int, y0: int) -> int:
    count = 0
    factors = get_factors(y0 // x0)
    for a in factors:
        b = y0 // x0 // a
        if gcd(a, b) == 1 and a != b:
            count += 2
        elif a == b:
            count += 1
    return count

def gcd(a, b):
    while b != 0:
        a, b = b, a % b
    return a

def get_factors(n):
    factors = []
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            factors.append(i)
            if n // i != i:
                factors.append(n // i)
    return factors

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.

    :param scenario: The name of the participant being tested as the potential criminal.
    :param liar_count: A set of names of participants who are assumed to be liars.
    :param statements: A dictionary mapping participant names to lists of their respective statements.
    :param days_of_week: A set of strings representing the days of the week.
    :return: True if the scenario is consistent with the statements, False otherwise.
    """
    # Check if the scenario is consistent with the statements
    for statement in statements[scenario]:
        if statement not in days_of_week:
            return False
    # Check if the other participants are consistent with the scenario
    for participant, statement_list in statements.items():
        if participant == scenario:
            continue
        if participant in liar_count and statement_list[0] not in days_of_week:
            return False
    return True

